package main

import (
	"bufio"
	"fmt"
	"os"
)

func isLucky(x int64) bool {
	if x == 0 {
		return false
	}
	for x > 0 {
		d := x % 10
		if d != 4 && d != 7 {
			return false
		}
		x /= 10
	}
	return true
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, k int64
	fmt.Fscan(in, &n, &k)

	fact := make([]int64, 14)
	fact[0] = 1
	for i := 1; i <= 13; i++ {
		fact[i] = fact[i-1] * int64(i)
	}

	m := 13
	if n < int64(m) {
		m = int(n)
	}

	if k > fact[m] {
		fmt.Println(-1)
		return
	}

	start := n - int64(m) + 1
	available := make([]int64, m)
	for i := 0; i < m; i++ {
		available[i] = start + int64(i)
	}

	permutation := make([]int64, m)
	rank := k - 1

	for i := 0; i < m; i++ {
		blockSize := fact[m-i-1]
		index := int(rank / blockSize)
		rank %= blockSize

		permutation[i] = available[index]
		available = append(available[:index], available[index+1:]...)
	}

	answer := 0

	var generate func(int64)
	generate = func(x int64) {
		if x > n {
			return
		}
		if x > 0 {
			if x < start {
				answer++
			} else if isLucky(permutation[int(x-start)]) {
				answer++
			}
		}

		if x == 0 {
			generate(4)
			generate(7)
		} else {
			generate(x*10 + 4)
			generate(x*10 + 7)
		}
	}

	generate(0)

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}

